const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format((v||0)/100);
const decimal=v=>((v||0)/100).toFixed(2);
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const qty=p=>Object.values(p.stock||{}).reduce((a,b)=>a+b,0);
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',inventory:'m3 7 9-4 9 4v10l-9 4-9-4Zm0 0 9 4 9-4M12 11v10M7.5 5l9 4',billing:'M6 3h12v18l-3-2-3 2-3-2-3 2ZM9 7h6M9 11h6M9 15h3',analytics:'M4 20h17M7 16v-5M12 16V5M17 16V8',assistant:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z',customers:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 4a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',suppliers:'M3 21V7l9-4 9 4v14M1 21h22M7 9h2M15 9h2M7 13h2M15 13h2M10 21v-5h4v5',purchases:'M2 3h3l3 12h10l3-8H6M9 20h.01M18 20h.01',expenses:'M3 6h18v14H3ZM3 6V4h15v2M16 11h5v5h-5Z',reports:'M5 3h10l4 4v14H5ZM14 3v5h5M8 12h8M8 16h8',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',sun:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1 1M18 18l1 1M5 19l1-1M18 6l1-1',menu:'M4 6h16M4 12h16M4 18h16',plus:'M12 5v14M5 12h14',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',check:'m5 12 4 4L19 6',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',arrow:'M5 12h14m-6-6 6 6-6 6',edit:'m14 5 5 5M4 20l4-1L21 6l-4-4L4 15ZM4 20h16',filter:'M4 4h16l-6 7v8l-4 2V11Z',box:'M4 4h16v16H4ZM4 9h16M9 4v5M10 14h4'};
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.box}"/></svg>`;
const navs=[['home','Home / Activity'],['inventory','Inventory'],['billing','Quotation & Billing'],['analytics','Analytics'],['assistant','AI Assistant'],['customers','Customers'],['suppliers','Suppliers'],['purchases','Purchases'],['expenses','Expenses'],['reports','Reports'],['settings','Settings']];
let state,route='home',tab='Product',query='',page=1,sort='name',taskFilter='Pending',docTab='All',lastFocus,toastTimer;
const perms={owner:['*'],administrator:['*'],manager:['inventory','contacts','documents','purchases','tasks','expenses','export'],inventory:['inventory','purchases','tasks'],finance:['documents','contacts','expenses','export','tasks'],viewer:[]};
const can=area=>perms[state?.user.role]?.some(x=>x==='*'||x===area);
const button=(text,action,id='',primary=false)=>`<button data-action="${action}" data-id="${esc(id)}" class="${primary?'primary':''}">${text}</button>`;
const badge=(text,kind='')=>`<span class="badge ${kind}">${esc(text)}</span>`;
const empty=(title,text,action='')=>`<div class="empty">${icon('box')}<strong>${esc(title)}</strong>${esc(text)}${action?'<div>'+action+'</div>':''}</div>`;
function notify(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
async function api(endpoint,data){
  const r=await fetch('/api/'+endpoint,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});
  const b=await r.json();if(r.status===401){location.href='/?reason=session-expired'+(route==='assistant'?'&next=assistant':'');throw Error('Your session expired. Please sign in again.');}if(!r.ok)throw Error(b.error);return b;
}
async function refresh(){state=await api('state');$('#business-name').textContent=state.business;$('#user-name').textContent=state.user.name;$('#user-role').textContent=state.user.role;$('#avatar').textContent=state.user.name.slice(0,2).toUpperCase();render();}
function modal(title,html){lastFocus=document.activeElement;$('#modal-title').textContent=title;$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function close(){ $('#modal').close(); }
$('#close-modal').onclick=close;$('#modal').addEventListener('close',()=>lastFocus?.focus());
function field(name,label,value='',type='text',options=null,required=false,wide=false){
  let input=options?`<select name="${name}" ${required?'required':''}>${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`;}).join('')}</select>`:type==='textarea'?`<textarea name="${name}" rows="3">${esc(value)}</textarea>`:`<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'step="any"':''}>`;
  return `<label class="field ${wide?'wide':''}"><span>${esc(label)}</span>${input}</label>`;
}
function form(title,html,onSubmit,submit='Save changes'){
  modal(title,`<form id="editor"><div class="form-grid">${html}</div><p class="form-error" role="alert"></p><div class="form-actions"><button type="button" data-action="close">Cancel</button><button type="submit" class="primary">${submit} ${icon('arrow')}</button></div></form>`);
  $('#editor').onsubmit=async e=>{e.preventDefault();const f=e.target,btn=f.querySelector('[type=submit]');btn.disabled=true;try{await onSubmit(Object.fromEntries(new FormData(f)),f);close();await refresh();notify('Saved to your workspace.');}catch(err){f.querySelector('.form-error').textContent=err.message;}finally{btn.disabled=false;}};
}
function confirmAction(title,text,fn){modal(title,`<p class="hint">${esc(text)}</p><p class="form-error" role="alert"></p><div class="form-actions">${button('Cancel','close')}<button class="primary" id="confirm-action">Confirm</button></div>`);$('#confirm-action').onclick=async e=>{e.target.disabled=true;try{await fn();close();await refresh();notify('Workspace updated.');}catch(err){$('.form-error').textContent=err.message;e.target.disabled=false;}};}
const heading=(title,description,actions='')=>`<div class="page-heading"><div><div class="eyebrow">YOUR BUSINESS, BEAUTIFULLY CONNECTED</div><h1>${esc(title)}</h1><p>${esc(description)}</p></div><div class="actions">${actions}</div></div>`;
const stat=(label,value,note,ic)=>`<div class="card stat"><div class="stat-top">${esc(label)}<span class="stat-icon">${icon(ic)}</span></div><strong>${esc(value)}</strong><small>${esc(note)}</small></div>`;
const panel=(title,body,action='',subtitle='')=>`<section class="panel"><div class="panel-head"><div><h2>${esc(title)}</h2>${subtitle?`<small>${esc(subtitle)}</small>`:''}</div>${action}</div><div class="panel-body">${body}</div></section>`;
const table=(headers,rows)=>`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;
function searchBar(placeholder='Search records…'){return `<input class="filter-search" id="filter-search" placeholder="${placeholder}" value="${esc(query)}" aria-label="${placeholder}">`;}
function filter(items){return items.filter(x=>JSON.stringify(x).toLowerCase().includes(query.toLowerCase()));}
function paginated(items){return items.slice((page-1)*15,page*15);}
function pagination(count){const pages=Math.max(1,Math.ceil(count/15));return `<div class="table-footer"><span>${count} records · Page ${page} of ${pages}</span><div class="actions"><button data-action="previous" ${page<=1?'disabled':''}>Previous</button><button data-action="next" ${page>=pages?'disabled':''}>Next</button></div></div>`;}
function taskRow(t){return `<div class="activity"><div class="activity-icon">${icon(t.module||'clock')}</div><div class="activity-main"><strong>${esc(t.title)}</strong><small>${esc(t.due)} · ${esc(t.assignee)} · ${esc(t.department)}</small></div><div class="activity-actions">${badge(t.status==='Completed'?'Completed':t.due<today()?'Overdue':t.priority,t.status==='Completed'?'green':t.due<today()?'red':t.priority==='High'?'amber':'blue')}${t.record?button('Open','task-open',t.id):''}${can('tasks')?button(t.status==='Completed'?'Reopen':icon('check'),'task-toggle',t.id):''}</div></div>`;}
function home(){
  const pending=state.tasks.filter(t=>t.status==='Pending'),due=pending.filter(t=>t.due<=today()),low=state.products.filter(p=>!p.archived&&qty(p)<=p.reorder);
  const tasks=filter(state.tasks.filter(t=>taskFilter==='All'||t.status===taskFilter).filter(t=>workflowUI.filterTask(t))).sort((a,b)=>a.due.localeCompare(b.due));
  return heading(`Let’s grow, ${state.user.name.split(' ')[0]}.`,'Your day at a glance. A little clarity for everything that comes next.',can('tasks')?button(icon('plus')+' New activity','task-new','',true):'')+
    `<div class="cards">${stat('Pending activities',pending.length,'Work waiting for your attention','clock')}${stat('Low-stock items',low.length,'At or below their reorder level','inventory')}${stat('Payments received',money(state.metrics.received),'All recorded payments','expenses')}${stat('Outstanding invoices',money(state.metrics.receivables),'Unpaid issued invoice balances','billing')}</div>`+
    (state.user.email.endsWith('@example.invalid')?`<div class="welcome-banner"><div><strong>Your business, with room to grow.</strong><p>This is your isolated demo workspace. Try editing stock, issuing an invoice, or recording a payment.</p></div>${button('Explore inventory '+icon('arrow'),'navigate','inventory')}</div>`:'')+
    `<div class="grid-two">${panel('Your activity center',`<div class="toolbar"><div class="tabs">${['Pending','Completed','All'].map(x=>`<button class="${taskFilter===x?'active':''}" data-action="task-filter" data-id="${x}">${x}</button>`).join('')}</div>${searchBar('Search activity or assignee…')}</div>${tasks.length?tasks.slice(0,15).map(taskRow).join(''):empty('A little breathing room.','No activities match this view.')}`,badge(`${due.length} need attention`,'amber'))}${panel('Coming up next',pending.filter(t=>t.due>today()).sort((a,b)=>a.due.localeCompare(b.due)).slice(0,5).map(taskRow).join('')||empty('Nothing scheduled yet.','Add an activity with a future due date.'),icon('clock'))}</div>`+
    `<div class="grid-two">${panel('Recent workspace activity',state.audit.slice(0,6).map(a=>`<div class="activity"><div class="activity-icon">${icon('check')}</div><div class="activity-main"><strong>${esc(a.action)}</strong><small>${esc(a.actor)} · ${new Date(a.created).toLocaleString('en-IN')}</small></div></div>`).join('')||empty('Your story starts here.','Your business actions will appear here.'))}${panel('Business pulse',`<div class="metric-list"><div>Active products <span>${state.products.filter(p=>p.type==='Product'&&!p.archived).length}</span></div><div>Parts & components <span>${state.products.filter(p=>p.type==='Part'&&!p.archived).length}</span></div><div>Open quotations <span>${state.documents.filter(d=>d.type==='Quotation'&&['Draft','Sent','Accepted'].includes(d.status)).length}</span></div><div>Expected purchases <span>${state.purchases.filter(p=>['Ordered','Partially received'].includes(p.status)).length}</span></div><div>Inventory value at current cost <span>${money(state.metrics.stockValue)}</span></div></div>`)}</div>`;
}
const standardColumns=[['name','Product / part'],['sku','SKU'],['category','Category'],['warehouse','Warehouse'],['stock','Stock'],['status','Status'],['price','Price'],['value','Stock value']];
function columns(){
  const fields=state.fields.filter(f=>!f.hidden&&(f.scope==='All'||f.scope===tab)).sort((a,b)=>a.order-b.order);
  const all=[...standardColumns,...fields.map(f=>[f.id,f.name])];const pref=state.preferences.find(p=>p.userId===state.user.id)?.columns;
  return pref?.length?pref.map(id=>all.find(c=>c[0]===id)).filter(Boolean):all;
}
function inventory(){
  let items=filter(state.products.filter(p=>tab==='Archived'?p.archived:p.type===tab&&!p.archived));
  items.sort((a,b)=>sort==='stock'?qty(a)-qty(b):sort==='price'?a.price-b.price:String(a[sort]||a.custom?.[sort]||'').localeCompare(String(b[sort]||b.custom?.[sort]||'')));
  const cols=columns();
  const rows=paginated(items).map(p=>{const values={name:`<div class="item-name"><span class="item-icon">${icon('inventory')}</span><div><strong>${esc(p.name)}</strong><small>${esc(p.unit)}${p.expiry?' · Exp. '+esc(p.expiry):''}</small></div></div>`,sku:esc(p.sku),category:esc(p.category||'—'),warehouse:esc(Object.keys(p.stock).map(id=>state.warehouses.find(w=>w.id===id)?.name).join(', ')||'—'),stock:`<strong>${qty(p)}</strong>`,status:badge(qty(p)===0?'Out of stock':qty(p)<=p.reorder?'Low stock':'In stock',qty(p)===0?'red':qty(p)<=p.reorder?'amber':'green'),price:money(p.price),value:money(qty(p)*p.cost)};
    return `<tr>${cols.map(([key])=>`<td>${values[key]??esc(p.custom?.[key]??'—')}</td>`).join('')}<td><div class="row-actions">${button('View','product-view',p.id)}${can('inventory')?button('Stock ±','stock',p.id):''}</div></td></tr>`;});
  return heading('Inventory','Every product. Every part. Everything in its place.',`${can('export')?button(icon('download')+' Export Excel','export','inventory'):''}${can('inventory')?button('Import Excel','import')+button(icon('plus')+' Add '+(tab==='Part'?'part':'product'),'product-new','',true):''}`)+
    `<div class="cards">${stat('Products',state.products.filter(p=>p.type==='Product'&&!p.archived).length,'Finished goods in your catalogue','inventory')}${stat('Parts & components',state.products.filter(p=>p.type==='Part'&&!p.archived).length,'Materials and components','box')}${stat('Inventory value',money(state.metrics.stockValue),'Quantity × current unit cost','analytics')}${stat('Low-stock items',state.products.filter(p=>!p.archived&&qty(p)<=p.reorder).length,'Replenishment suggestions in Home','clock')}</div>`+
    `<section class="panel"><div class="toolbar"><div class="tabs">${['Product','Part','Archived'].map(x=>`<button data-action="inventory-tab" data-id="${x}" class="${tab===x?'active':''}">${x==='Product'?'Products':x==='Part'?'Parts & Components':'Archived'}</button>`).join('')}</div><div class="actions">${button(icon('filter')+' Columns','columns')}${can('settings')?button('+ Custom field','field-new'):''}</div></div><div class="toolbar">${searchBar('Search name, SKU, custom fields…')}<label>Sort <select id="inventory-sort" aria-label="Sort inventory">${[...standardColumns.filter(c=>['name','sku','category','stock','price'].includes(c[0])),...state.fields.map(f=>[f.id,f.name])].map(([v,l])=>`<option value="${v}" ${sort===v?'selected':''}>${esc(l)}</option>`).join('')}</select></label></div>${rows.length?table([...cols.map(c=>esc(c[1])),'Actions'],rows):empty('Your inventory starts here.','Add a product or part, then receive its opening stock.')}${pagination(items.length)}</section>`;
}
function paymentStatus(d){return d.type==='Invoice'&&d.status==='Issued'?(d.paid+(d.credited||0)>=d.total?(d.credited?'Settled':'Paid'):d.due<today()?'Overdue':d.paid>0?'Partially paid':'Unpaid'):d.status;}
function ordersPanel(){
  return panel('Orders & deliveries',state.orders.length?table(['Order','Customer','Due','Status','Next action'],state.orders.map(o=>`<tr><td><strong>${esc(o.number)}</strong><small>${esc(o.documentNumber)}</small></td><td>${esc(o.customer)}</td><td>${esc(o.due)}</td><td>${badge(o.status,o.status==='Delivered'?'green':'blue')}</td><td><div class="row-actions">${button('Details','order-view',o.id)}${can('inventory')&&['Confirmed','Packed','Dispatched'].includes(o.status)?button({Confirmed:'Mark packed',Packed:'Dispatch',Dispatched:'Mark delivered'}[o.status],'order-status',o.id):''}</div></td></tr>`)):empty('Ready for your next order.','Accept a quotation to create a sales order and track its delivery.'),'','Confirmed → Packed → Dispatched → Delivered');
}
function billing(){
  const docs=filter(state.documents.filter(d=>d.status!=='Deleted'&&(docTab==='All'||d.type===docTab)));
  return heading('Quotation & Billing','From your first proposal to your next payment.',can('documents')?button(icon('plus')+' Create document','document-new','',true):'')+
    `<div class="cards">${stat('Quotations',state.documents.filter(d=>d.type==='Quotation').length,'Proposals prepared for customers','billing')}${stat('Invoiced revenue',money(state.metrics.revenue),'Issued sales excluding tax and credits','analytics')}${stat('Payments received',money(state.metrics.received),'Cash recorded against invoices','expenses')}${stat('Outstanding',money(state.metrics.receivables),'Remaining invoice balances','clock')}</div>`+
    `<section class="panel"><div class="toolbar"><div class="tabs">${['All','Quotation','Invoice','Proforma','Credit Note'].map(x=>`<button data-action="document-tab" data-id="${x}" class="${docTab===x?'active':''}">${x==='All'?'All documents':x}</button>`).join('')}</div>${searchBar('Search document or customer…')}</div>${docs.length?table(['Document','Customer','Issue date','Due date','Amount','Status','Actions'],paginated(docs).map(d=>`<tr><td><strong>${esc(d.number)}</strong><small>${esc(d.type)}</small></td><td>${esc(d.customer.name)}</td><td>${esc(d.date)}</td><td>${esc(d.due)}</td><td><strong>${money(d.total)}</strong></td><td>${badge(paymentStatus(d),paymentStatus(d)==='Paid'?'green':paymentStatus(d)==='Overdue'?'red':d.status==='Draft'?'':'blue')}</td><td>${button('Open document','document-view',d.id)}${can('documents')?button('Share','document-share',d.id):''}</td></tr>`)):empty('Your next deal starts here.','Add a customer and create your first quotation.')}${pagination(docs.length)}</section>`;
}
function contacts(kind){
  const list=filter(state[kind]);const customer=kind==='customers';
  return heading(customer?'Customers':'Suppliers',customer?'The relationships behind your growth.':'Your supply network, in one place.',can('contacts')?button(icon('plus')+` Add ${customer?'customer':'supplier'}`,'contact-new',kind,true):'')+
    `<section class="panel"><div class="toolbar"><strong>${list.length} ${kind}</strong>${searchBar('Search name, email, or phone…')}</div>${list.length?table(['Contact','Email','Phone',customer?'Segment':'GSTIN','Actions'],paginated(list).map(c=>`<tr><td><div class="item-name"><span class="item-icon">${icon(kind)}</span><div><strong>${esc(c.name)}</strong><small>${esc(c.address)}</small></div></div></td><td>${esc(c.email||'—')}</td><td>${esc(c.phone||'—')}</td><td>${esc(customer?c.segment||'—':c.gstin||'—')}</td><td><div class="row-actions">${button('View','contact-view',kind+':'+c.id)}${can('contacts')?button('Edit','contact-edit',kind+':'+c.id):''}</div></td></tr>`)):empty('A new connection starts here.',`Add your first ${customer?'customer':'supplier'} to connect business records.`)}${pagination(list.length)}</section>`;
}
function purchases(){
  const items=filter(state.purchases);
  return heading('Purchases','Plan your replenishment. Keep your business moving.',can('purchases')?button(icon('plus')+' Purchase order','purchase-new','',true):'')+
    `<section class="panel"><div class="toolbar"><strong>${items.filter(p=>['Ordered','Partially received'].includes(p.status)).length} awaiting receipt</strong>${searchBar()}</div>${items.length?table(['Purchase order','Supplier','Expected','Value before tax','Status','Actions'],paginated(items).map(p=>`<tr><td><strong>${esc(p.number)}</strong><small>${p.lines.length} line items</small></td><td>${esc(p.supplier)}</td><td>${esc(p.due)}</td><td>${money(p.total)}</td><td>${badge(p.status,p.status==='Received'?'green':'amber')}</td><td>${button('View','purchase-view',p.id)} ${can('purchases')&&['Ordered','Partially received'].includes(p.status)?button('Receive goods','purchase-receive',p.id):''}</td></tr>`)):empty('Stock up for what’s next.','Create a purchase order, then receive it to update inventory.')}${pagination(items.length)}</section>`;
}
function expenses(){
  const items=filter(state.expenses);
  return heading('Expenses','A clear view of the cost of doing business.',can('expenses')?button(icon('plus')+' Record expense','expense-new','',true):'')+
    `<div class="cards">${stat('Recorded expenses',money(state.metrics.expenses),'All recorded dates','expenses')}${stat('Expense records',state.expenses.length,'Preserved in your activity history','reports')}${stat('Categories',new Set(state.expenses.map(e=>e.category)).size,'Where your money goes','analytics')}${stat('This month',money(state.expenses.filter(e=>e.date.slice(0,7)===today().slice(0,7)).reduce((s,e)=>s+e.amount,0)),'Based on the expense date','clock')}</div><section class="panel"><div class="toolbar"><strong>Expense history</strong>${searchBar()}</div>${items.length?table(['Description','Category','Date','Reference','Amount','Actions'],paginated(items).map(e=>`<tr><td><strong>${esc(e.description)}</strong></td><td>${esc(e.category)}</td><td>${esc(e.date)}</td><td>${esc(e.reference||'—')}</td><td>${money(e.amount)}</td><td>${can('expenses')?button('Correct','wf-expense-correct',e.id):''}${button('History','wf-history','expenses:'+e.id)}</td></tr>`)):empty('Every expense counts.','Record your operating costs to see a clearer profit estimate.')}${pagination(items.length)}</section>`;
}
function assistantDraft(value){const draftKey='gh-assistant-draft:'+state?.user.id;try{if(value===null)sessionStorage.removeItem(draftKey);else if(value!==undefined)sessionStorage.setItem(draftKey,value);return sessionStorage.getItem(draftKey)||'';}catch{return '';}}
function assistant(){
  return heading('AI Assistant','Your business questions, grounded in your own workspace.')+(state.serverVersion!=='0.4.1'?'<div class="note" role="alert"><strong>Server update required.</strong> This browser is connected to an older running server. Open Restart-Grow-High.cmd in your app folder and use the address it opens. Your data stays saved.</div>':'')+`<div class="chat-wrap"><div class="assistant-intro"><div class="assistant-symbol">${icon('assistant')}</div><h2>A little insight. A better next move.</h2><p class="hint">Business assistant · calculated answers from your saved records.<br>Generative AI and forecasting are not connected.</p><div class="suggestions">${['Which products have low stock?','Which invoices are overdue?','Top products this month','Expenses last month','Show my revenue and profit.'].map(q=>button(esc(q),'ask',q)).join('')}</div></div><div>${[...state.chat].reverse().map(c=>`<div class="message user">${esc(c.question)}</div><div class="message"><small>${esc(c.engine)}</small>${esc(c.answer)}<div class="actions">${c.links.map(l=>button('Open '+navs.find(n=>n[0]===l)?.[1],'navigate',l)).join('')}</div></div>`).join('')}</div><p id="assistant-status" role="status" aria-live="polite"></p><form class="chat-input" id="chat-form"><input name="question" value="${esc(assistantDraft())}" aria-label="Ask about your business" placeholder="Ask about stock, invoices, profit, or today's work…" required maxlength="1000"><button class="primary" type="submit">${icon('arrow')} Ask</button></form></div>`;
}
function reports(){
  return heading('Reports','Your business records, ready for a closer look.',can('export')?button(icon('download')+' Export workspace JSON','backup'):'')+
    `<div class="settings-grid">${[['inventory','Inventory report','Products, parts, stock balances, and custom fields.'],['sales','Sales & billing','Quotations, issued invoices, taxes, and balances.'],['payments','Payment history','Cash receipts, payment references, and invoice links.'],['expenses','Expense report','Operating expenses by date and category.'],['purchases','Purchase orders','Supplier orders and goods-receipt status.'],['audit','Audit history','Who changed what, and when.']].map(([key,title,desc])=>panel(title,`<p class="hint">${desc}</p>${can('export')?button(icon('download')+' Download Excel','export',key):'<p class="hint">Your role does not include export permission.</p>'}`)).join('')}</div>`;
}
function settings(){
  return heading('Workspace settings','Make Grow High work the way your business does.')+
    `<div class="settings-grid">${panel('Company profiles',`<div class="settings-list">${state.companies.map(c=>`<div><div><strong>${esc(c.name)}</strong><small>${esc(c.gstin||'GSTIN not set')} · ${esc(c.email)}</small></div>${can('settings')?button('Edit','company-edit',c.id):''}</div>`).join('')}</div>${can('settings')?button('+ Add company','company-new'):''}`,'','Your company appears in document headers.')}${panel('Warehouses & branches',`<div class="settings-list">${state.warehouses.map(w=>`<div><strong>${esc(w.name)}</strong>${badge('Active','green')}</div>`).join('')}</div>${can('settings')?button('+ Add warehouse','warehouse-new'):''}`)}${panel('Custom inventory fields',`<div class="settings-list">${state.fields.map(f=>`<div><div><strong>${esc(f.name)}</strong><small>${esc(f.type)} · ${esc(f.scope)}${f.required?' · Required':''}</small></div>${can('settings')?button('Edit','field-edit',f.id):''}</div>`).join('')||'<p class="hint">Add fields such as manufacturer, warranty, or supplier code.</p>'}</div>${can('settings')?button('+ Add custom field','field-new'):''}`)}${panel('Team & permissions',`<div class="settings-list">${state.users.map(u=>`<div><div><strong>${esc(u.name)}</strong><small>${esc(u.email)} · ${esc(u.role)}${!u.active?' · Disabled':''}</small></div>${u.role!=='owner'?button('Access','user-edit',u.id):badge('Owner','blue')}</div>`).join('')||'<p class="hint">Team settings are visible to administrators.</p>'}</div>${can('settings')?button('+ Add team member','user-new'):''}`)}${panel('Automation',`<div class="settings-list"><div><div><strong>Low-stock reminders</strong><small>Creates replenishment activities from saved balances.</small></div>${badge(state.workflowSettings[0]?.lowStock===false?'Paused':'Running','green')}</div><div><div><strong>Overdue invoice follow-ups</strong><small>Checks every minute while the server is running.</small></div>${badge(state.workflowSettings[0]?.overdue===false?'Paused':'Running','green')}</div><div><div><strong>Accepted quotation activities</strong><small>Creates fulfilment work on acceptance.</small></div>${badge('Running','green')}</div></div>`)}${panel('Integrations & deployment',`<p class="hint">This edition runs on your computer. Email delivery, Google sign-in, generative AI, payment gateways, WhatsApp, and cloud backups require external service configuration. Subscription billing is not active.</p><p class="hint">Account recovery uses the recovery code saved at registration. For hosted use, migrate authentication to an established provider and add HTTPS, backups, monitoring, and deployment security review.</p>${can('export')?button('Export business data','backup'):''}`)}</div>`;
}
const analyticsUI=window.createAnalyticsUI({state:()=>state,esc,money,heading,panel,table,button,api,notify,can,today,render,download});
const sharingUI=window.createSharingUI({api,esc,modal,button,documentView,download,notify});
function analytics(){return analyticsUI.view();}
const workflowUI=window.createWorkflowUI({state:()=>state,esc,money,decimal,button,badge,panel,table,field,form,modal,api,refresh,notify,can,confirmAction,today,render,close});
function render(){
  analyticsUI.destroy();
  route=location.hash.slice(1)||'home';if(!navs.some(n=>n[0]===route))route='home';
  $('#nav').innerHTML=navs.map(([id,label],i)=>`${i===5?'<hr>':''}<a href="#${id}" class="${route===id?'active':''}">${icon(id)}<span>${label}</span>${id==='home'&&state.tasks.filter(t=>t.status==='Pending').length?`<i>${state.tasks.filter(t=>t.status==='Pending').length}</i>`:''}</a>`).join('');
  $('#crumb').textContent=navs.find(n=>n[0]===route)[1];document.title=`${$('#crumb').textContent} · Grow High`;
  const views={home:()=>home()+ordersPanel(),inventory,billing,analytics,assistant,customers:()=>contacts('customers'),suppliers:()=>contacts('suppliers'),purchases,expenses,reports,settings};
  $('#content').innerHTML=views[route]()+({purchases:()=>workflowUI.purchasePanels(),billing:()=>workflowUI.billingPanels(),settings:()=>workflowUI.settingsPanels()}[route]?.()||'');
  if(route==='home')workflowUI.enhanceHome();
  if(route==='analytics'&&typeof fetch==='function')analyticsUI.mount();
  if($('#filter-search'))$('#filter-search').oninput=e=>{const cursor=e.target.selectionStart;query=e.target.value;page=1;render();$('#filter-search').focus();$('#filter-search').setSelectionRange(cursor,cursor);};
  if($('#inventory-sort'))$('#inventory-sort').onchange=e=>{sort=e.target.value;render();};
  if($('#chat-form'))$('#chat-form').onsubmit=async e=>{e.preventDefault();await ask(e.target.question.value);};
}
function productForm(id){
  const p=state.products.find(x=>x.id===id)||{type:tab==='Archived'?'Product':tab,custom:{},price:0,cost:0,reorder:5};
  const custom=state.fields.filter(f=>f.scope==='All'||f.scope===p.type).map(f=>field('custom_'+f.id,f.name,p.custom[f.id]??f.default??'',f.type==='Date'?'date':['Number','Currency'].includes(f.type)?'number':'text',f.type==='Dropdown'?['',...f.options]:f.type==='Boolean'?[['','Not set'],['true','Yes'],['false','No']]:null,f.required)).join('');
  form(id?'Edit '+p.name:'Add '+(tab==='Part'?'a part':'a product'),field('name','Name',p.name,'text',null,true)+field('sku','SKU',p.sku,'text',null,true)+field('type','Inventory type',p.type,'text',['Product','Part'],true)+field('category','Category',p.category)+field('price','Selling price (₹)',decimal(p.price),'number',null,true)+field('cost','Unit cost (₹)',decimal(p.cost),'number',null,true)+field('reorder','Reorder level',p.reorder,'number')+field('unit','Unit of measure',p.unit||'pcs')+field('barcode','Barcode',p.barcode)+field('batch','Batch / serial reference',p.batch)+field('expiry','Expiry date',p.expiry,'date')+custom,async b=>{const custom={};for(const f of state.fields)if(b['custom_'+f.id]!==undefined)custom[f.id]=b['custom_'+f.id];await api('products',{...b,id:p.id,version:p.version,custom});},id?'Save product':'Create product');
}
function productView(id){
  const p=state.products.find(x=>x.id===id),bom=state.bom.find(x=>x.productId===id);
  modal(p.name,`<div class="cards" style="grid-template-columns:1fr 1fr">${stat('Available stock',qty(p),p.unit,'inventory')}${stat('Selling price',money(p.price),'Per '+p.unit,'expenses')}</div><div class="hint">SKU ${esc(p.sku)} · ${esc(p.type)} · ${esc(p.category)}</div><div class="section-title">Warehouse balances</div>${table(['Warehouse','Quantity'],state.warehouses.map(w=>`<tr><td>${esc(w.name)}</td><td>${p.stock[w.id]||0}</td></tr>`))}<div class="section-title">Recent stock history</div>${table(['Date','Change','Reason','Reference'],state.transactions.filter(t=>t.productId===id).slice(0,10).map(t=>`<tr><td>${esc(t.date)}</td><td>${t.delta>0?'+':''}${t.delta}</td><td>${esc(t.reason)}</td><td>${esc(t.reference)}</td></tr>`))}${bom?`<div class="section-title">Bill of materials</div><p class="hint">${bom.components.map(c=>`${esc(state.products.find(p=>p.id===c.productId)?.name)} × ${c.quantity}`).join('<br>')}</p>`:''}<div class="form-actions">${can('inventory')?button('Edit','product-edit',id)+button('Adjust stock','stock',id)+button('Transfer','transfer',id)+(p.type==='Product'?button('Bill of materials','bom',id)+button('Assemble','assemble',id):'')+button(p.archived?'Restore':'Archive','product-archive',id):''}</div>`);
}
