function columnForm(){
  const all=[...standardColumns,...state.fields.filter(f=>f.scope==='All'||f.scope===tab).map(f=>[f.id,f.name])],selected=columns().map(c=>c[0]);
  const ordered=[...selected,...all.map(c=>c[0]).filter(id=>!selected.includes(id))];
  modal('Make this table yours.',`<p class="hint">Choose visible columns. Drag rows to reorder them, or use the arrow buttons. Your layout is saved to your account.</p><div class="columns-list">${ordered.map(id=>`<div class="column-item" draggable="true" data-column="${id}"><label><input type="checkbox" value="${id}" ${selected.includes(id)?'checked':''}>${esc(all.find(c=>c[0]===id)?.[1]||id)}</label><div><button data-action="column-up" aria-label="Move column up">↑</button><button data-action="column-down" aria-label="Move column down">↓</button></div></div>`).join('')}</div><div class="form-actions">${button('Reset layout','columns-reset')}<button class="primary" id="save-columns">Save layout</button></div>`);
  let dragging;$$('.column-item').forEach(el=>{el.ondragstart=()=>dragging=el;el.ondragover=e=>e.preventDefault();el.ondrop=e=>{e.preventDefault();if(dragging&&dragging!==el)el.before(dragging);};});
  $('#save-columns').onclick=async()=>{const selected=$$('.column-item input:checked').map(x=>x.value);if(!selected.length)return notify('Choose at least one column.');await api('preferences',{columns:selected});close();await refresh();};
}
function documentForm(id){
  if(!state.customers.length)return notify('Add a customer before creating a document.');
  const d=state.documents.find(x=>x.id===id)||{type:'Quotation',date:today(),due:today(),lines:[]};
  const companies=state.companies.map(c=>[c.id,c.name]),customers=state.customers.map(c=>[c.id,c.name]);
  form(id?'Edit '+d.number:'Create a business document',field('type','Document type',d.type,'text',[d.type,...['Quotation','Invoice','Proforma','Credit Note'].filter(t=>t!==d.type)])+field('companyId','Company profile',d.companyId,'text',companies,true)+field('customerId','Customer',d.customerId,'text',customers,true)+field('warehouse','Stock warehouse',d.warehouse,'text',[['','No stock items'],...state.warehouses.map(w=>[w.id,w.name])])+field('date','Issue date',d.date,'date',null,true)+field('due','Due / valid-until date',d.due,'date',null,true)+field('taxMode','Tax treatment',d.taxMode||'CGST + SGST','text',['CGST + SGST','IGST'])+`<div class="wide field"><div class="section-title">Line items</div><div id="document-lines"></div><button type="button" id="add-line">+ Add line item</button><div class="total-preview" id="line-total"></div></div>`+field('notes','Notes & terms',d.notes||state.companies[0]?.terms,'textarea',null,false,true),async(b)=>{
    const lines=$$('#document-lines .line-row').map(row=>Object.fromEntries([...row.querySelectorAll('[data-line]')].map(el=>[el.dataset.line,el.value])));
    await api('documents',{...b,id:d.id,version:d.version,lines});
  },'Save draft');
  const creditField=document.createElement('div');creditField.className='wide field';creditField.innerHTML=field('sourceInvoiceId','Credit note: source invoice',d.sourceInvoiceId,'text',[['','Choose when creating a credit note'],...state.documents.filter(x=>x.type==='Invoice'&&x.status==='Issued').map(x=>[x.id,x.number+' · '+x.customer.name])]);$('#editor .form-grid').prepend(creditField);
  const syncCredit=()=>{creditField.hidden=$('#editor [name=type]').value!=='Credit Note';};
  $('#editor [name=type]').addEventListener('change',syncCredit);syncCredit();
  function addLine(l={}){
    const row=document.createElement('div');row.className='line-row';
    row.innerHTML=`<div><label>Product / service</label><select data-line="productId"><option value="">Custom service</option>${state.products.filter(p=>!p.archived).map(p=>`<option value="${p.id}" ${l.productId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><input data-line="description" aria-label="Line description" placeholder="Description" value="${esc(l.description||'')}" required></div><div><label>Qty</label><input data-line="quantity" aria-label="Quantity" type="number" min="1" step="1" value="${l.quantity||1}" required></div><div><label>Price ₹</label><input data-line="price" aria-label="Unit price" type="number" min="0" step=".01" value="${decimal(l.price)}" required></div><div><label>Disc %</label><input data-line="discount" aria-label="Discount percent" type="number" min="0" max="100" value="${l.discount||0}"></div><div><label>Tax %</label><input data-line="tax" aria-label="Tax percent" type="number" min="0" max="100" value="${l.tax??18}"></div><button type="button" aria-label="Remove line">×</button>`;
    row.querySelector('select').onchange=e=>{const p=state.products.find(x=>x.id===e.target.value);if(p){row.querySelector('[data-line=description]').value=p.name;row.querySelector('[data-line=price]').value=decimal(p.price);}updateTotal();};
    row.querySelector('button').onclick=()=>{row.remove();updateTotal();};row.oninput=updateTotal;$('#document-lines').append(row);updateTotal();
  }
  function updateTotal(){let total=0;$$('#document-lines .line-row').forEach(row=>{const v=key=>Number(row.querySelector(`[data-line=${key}]`).value);const base=Math.round(v('quantity')*Math.round(v('price')*100)*(100-v('discount'))/100);total+=base+Math.round(base*v('tax')/100);});$('#line-total').innerHTML='Estimated total <strong>'+money(total)+'</strong>';}
  $('#add-line').onclick=()=>addLine();(d.lines.length?d.lines:[{}]).forEach(addLine);
}
function documentView(id){
  const d=state.documents.find(x=>x.id===id);if(!d)return;
  const actions=can('documents')?(d.status==='Draft'?button('Edit draft','document-edit',id)+button(d.type==='Quotation'?'Mark as sent':'Issue document','document-status',id+':'+(d.type==='Quotation'?'Sent':'Issued')):'')+(d.type==='Quotation'&&d.status==='Sent'?button('Accept','document-status',id+':Accepted')+button('Reject','document-status',id+':Rejected'):'')+(d.type==='Quotation'&&d.status==='Accepted'?button('Convert to invoice','document-convert',id):'')+(d.type==='Invoice'&&d.status==='Issued'&&d.paid+(d.credited||0)<d.total?button('Record payment','payment-new',id,true):'')+button('Duplicate','document-duplicate',id)+(['Draft','Sent','Accepted','Issued'].includes(d.status)&&!d.paid&&!d.linkedInvoice?button('Cancel document','document-status',id+':Cancelled'):''):'';
  modal(d.number,`<div class="actions print-actions" style="margin-bottom:20px">${button(icon('download')+' Print / Save PDF','print')}${actions}</div><article class="document-paper"><div class="document-header"><div>${d.company.logo?`<img src="${esc(d.company.logo)}" alt="Company logo" style="max-width:140px;max-height:70px;object-fit:contain;margin-bottom:12px">`:``}<h2>${esc(d.company.name)}</h2><p>${esc(d.company.address)}\n${esc(d.company.email)} · ${esc(d.company.phone)}${d.company.gstin?'\nGSTIN: '+esc(d.company.gstin):''}</p></div><div><h3>${esc(d.type)}</h3><strong>${esc(d.number)}</strong><p>${esc(paymentStatus(d))}</p></div></div><div class="document-meta"><div><strong>Bill to</strong><p>${esc(d.customer.name)}\n${esc(d.customer.address)}\n${esc(d.customer.email)}${d.customer.gstin?'\nGSTIN: '+esc(d.customer.gstin):''}</p></div><div><p>Issue date: ${esc(d.date)}\nDue / valid until: ${esc(d.due)}</p></div></div>${table(['Description','Qty','Unit price','Disc.','Tax','Amount'],d.lines.map(l=>`<tr><td>${esc(l.description)}</td><td>${l.quantity}</td><td>${money(l.price)}</td><td>${l.discount}%</td><td>${l.tax}%</td><td>${money(l.total)}</td></tr>`))}<div class="document-totals"><div>Subtotal <span>${money(d.subtotal)}</span></div>${d.taxMode==='IGST'?`<div>IGST <span>${money(d.tax)}</span></div>`:`<div>CGST <span>${money(Math.floor(d.tax/2))}</span></div><div>SGST <span>${money(d.tax-Math.floor(d.tax/2))}</span></div>`}<div class="grand">Total <span>${money(d.total)}</span></div>${d.type==='Invoice'?`<div>Paid <span>${money(d.paid)}</span></div><div>Credits <span>${money(d.credited||0)}</span></div><div>Balance <span>${money(d.total-d.paid-(d.credited||0))}</span></div>`:''}</div><p><strong>Notes & terms</strong>\n${esc(d.notes||d.company.terms||'')}${d.company.bank?'\n\nPayment instructions:\n'+esc(d.company.bank):''}${d.company.signatory?'\n\nAuthorized signatory: '+esc(d.company.signatory):''}</p><div class="document-brand">Grow High</div></article>`);
  workflowUI.enhanceDocument(d);
  if(can('documents')&&d.status!=='Deleted')$('#modal-content .print-actions').insertAdjacentHTML('beforeend',button('Share','document-share',d.id));
}
function purchaseForm(){
  if(!state.suppliers.length||!state.products.length)return notify('Add a supplier and an inventory item first.');
  form('Create a purchase order',field('supplierId','Supplier','','text',state.suppliers.map(s=>[s.id,s.name]))+field('warehouse','Receiving warehouse','','text',state.warehouses.map(w=>[w.id,w.name]))+field('due','Expected receipt',today(),'date',null,true)+field('productId','Product / part','','text',state.products.filter(p=>!p.archived).map(p=>[p.id,p.name]))+field('quantity','Quantity',1,'number',null,true)+field('cost','Unit cost before tax (₹)',decimal(state.products.find(p=>!p.archived)?.cost||0),'number',null,true),b=>api('purchases',{...b,lines:[{productId:b.productId,quantity:b.quantity,cost:b.cost}]}),'Create purchase order');
}
function companyForm(id){
  const c=state.companies.find(x=>x.id===id)||{};
  form('Business profile',field('name','Company name',c.name,'text',null,true)+field('gstin','GSTIN',c.gstin)+field('email','Email',c.email,'email')+field('phone','Phone',c.phone)+field('website','Website',c.website)+field('signatory','Authorized signatory',c.signatory)+field('address','Registered address',c.address,'textarea',null,false,true)+field('bank','Payment instructions',c.bank,'textarea',null,false,true)+field('terms','Default document terms',c.terms,'textarea',null,false,true)+`<label class="field wide"><span>Company logo · PNG or JPEG, under 300 KB</span><input name="logoFile" type="file" accept="image/png,image/jpeg"></label>`,async(b,f)=>{
    const file=f.logoFile.files[0];let logo=c.logo||'';
    if(file){if(file.size>300000)throw Error('Choose a company logo under 300 KB.');logo=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Unable to read the logo.'));reader.readAsDataURL(file);});}
    delete b.logoFile;await api('companies',{...b,id,version:c.version,logo});
  });
}
async function excelDownload(name,headers,rows){await api('export-check');download(name+'.xlsx',await GrowExcel.buffer([{name:'Report',headers,rows:rows.map(r=>r.map((v,i)=>/INR|^Price$|^Stock value$/i.test(headers[i])&&v!==''?Number(v):v))}]),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');}
function download(name,content,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function exportReport(kind){
  if(!can('export'))return notify('Your role does not include export access.');
  if(kind==='inventory'){const cols=columns();await excelDownload('grow-high-inventory',cols.map(c=>c[1]),filter(state.products.filter(p=>!p.archived&&(route!=='inventory'||p.type===tab))).map(p=>cols.map(([k])=>({stock:qty(p),value:decimal(qty(p)*p.cost),price:decimal(p.price),warehouse:Object.keys(p.stock).map(id=>state.warehouses.find(w=>w.id===id)?.name).join('; '),status:qty(p)<=p.reorder?'Low stock':'In stock'}[k]??p[k]??p.custom[k]??''))));}
  if(kind==='sales')await excelDownload('grow-high-documents',['Number','Type','Customer','Date','Due','Subtotal INR','Tax INR','Total INR','Paid INR','Status'],state.documents.filter(d=>d.status!=='Deleted').map(d=>[d.number,d.type,d.customer.name,d.date,d.due,decimal(d.subtotal),decimal(d.tax),decimal(d.total),decimal(d.paid),paymentStatus(d)]));
  if(kind==='payments')await excelDownload('grow-high-payments',['Invoice','Date','Amount INR','Reference','Method'],state.payments.map(p=>[p.number,p.date,decimal(p.amount),p.reference,p.method]));
  if(kind==='expenses')await excelDownload('grow-high-expenses',['Description','Category','Date','Amount INR','Reference'],state.expenses.map(e=>[e.description,e.category,e.date,decimal(e.amount),e.reference]));
  if(kind==='purchases')await excelDownload('grow-high-purchases',['Number','Supplier','Due','Total INR','Status'],state.purchases.map(p=>[p.number,p.supplier,p.due,decimal(p.total),p.status]));
  if(kind==='audit')await excelDownload('grow-high-audit',['Actor','Action','Record','Timestamp'],state.audit.map(a=>[a.actor,a.action,a.record_id,a.created]));
}
let asking=false;
async function ask(question){
 question=String(question||'').trim();if(asking||!question)return;if(state.serverVersion!=='0.4.1'){const warning='This server is still running the older assistant. Open Restart-Grow-High.cmd and use the new address.';$('#assistant-status').textContent=warning;notify(warning);return;}asking=true;assistantDraft(question);
 const btn=$('#chat-form button'),status=$('#assistant-status');if(btn){btn.disabled=true;btn.textContent='Replying…';}if(status)status.textContent='Working on your question…';
 try{await api('assistant',{question});assistantDraft(null);await refresh();$('#chat-form input')?.focus();$('#chat-form')?.scrollIntoView?.({block:'end',behavior:'smooth'});}
 catch(e){if(status)status.textContent=e.message+' Your question is kept above; try again after resolving the error.';notify(e.message);}
 finally{asking=false;if(btn){btn.disabled=false;btn.textContent='Ask';}}
}
async function action(name,id='',el){
  if(await analyticsUI.action(name,id))return;
  if(await sharingUI.action(name,id))return;
  if(await workflowUI.action(name,id,el))return;
  switch(name){
    case 'close':close();break;
    case 'navigate':close();location.hash=id;break;
    case 'previous':page--;render();break;case 'next':page++;render();break;
    case 'inventory-tab':tab=id;page=1;query='';render();break;
    case 'task-filter':taskFilter=id;query='';render();break;
    case 'document-tab':docTab=id;query='';page=1;render();break;
    case 'product-new':productForm();break;case 'product-edit':productForm(id);break;case 'product-view':productView(id);break;
    case 'product-archive':{const p=state.products.find(p=>p.id===id);confirmAction('Archive product?', 'The record and transaction history will remain saved.',()=>api('products/archive',{id,version:p.version}));break;}
    case 'stock':stockForm(id);break;case 'transfer':stockForm(id,true);break;
    case 'bom':{
      const b=state.bom.find(b=>b.productId===id);const parts=state.products.filter(p=>p.type==='Part'&&!p.archived);
      if(!parts.length)return notify('Add parts before defining a bill of materials.');
      form('Bill of materials',`<p class="hint wide">Set the quantity of each component required per finished product. Leave unused parts at zero.</p>`+parts.map(p=>field(p.id,p.name,b?.components.find(c=>c.productId===p.id)?.quantity||0,'number')).join(''),v=>api('bom',{productId:id,components:Object.entries(v).filter(([,q])=>Number(q)>0).map(([productId,quantity])=>({productId,quantity}))}));break;}
    case 'assemble':form('Assemble finished products',field('warehouse','Warehouse','','text',state.warehouses.map(w=>[w.id,w.name]))+field('quantity','Quantity to build',1,'number',null,true),b=>api('assemble',{...b,productId:id}),'Confirm assembly');break;
    case 'field-new':customFieldForm();break;case 'field-edit':customFieldForm(id);break;
    case 'columns':columnForm();break;
    case 'column-up':{const row=el.closest('.column-item');row.previousElementSibling?.before(row);break;}
    case 'column-down':{const row=el.closest('.column-item');row.nextElementSibling?.after(row);break;}
    case 'columns-reset':await api('preferences',{columns:[]});close();await refresh();break;
    case 'contact-new':contactForm(id);break;
    case 'contact-edit':{const [kind,key]=id.split(':');contactForm(kind,key);break;}
    case 'contact-view':{
      const [kind,key]=id.split(':'),c=state[kind].find(c=>c.id===key),docs=kind==='customers'?state.documents.filter(d=>d.customerId===key):state.purchases.filter(p=>p.supplierId===key);
      modal(c.name,`<p class="hint">${esc(c.email)} · ${esc(c.phone)}<br>${esc(c.address)}<br>${esc(c.gstin)}</p><div class="section-title">Related business records</div>${docs.map(d=>`<div class="activity"><div class="activity-main"><strong>${esc(d.number)}</strong><small>${esc(d.status)} · ${money(d.total)}</small></div>${button('Open',kind==='customers'?'document-view':'purchase-view',d.id)}</div>`).join('')||empty('No transactions yet.','Linked documents will appear here.')}`);break;}
    case 'document-new':documentForm();break;case 'document-edit':documentForm(id);break;case 'document-view':documentView(id);break;
    case 'document-status':{
      const [key,status]=id.split(':'),d=state.documents.find(d=>d.id===key);
      confirmAction(`${status} ${d.number}?`,status==='Issued'&&d.type==='Invoice'?'Issuing locks the document and deducts its inventory items atomically.':'This change will be recorded in your activity history.',()=>api('documents/status',{id:key,status,version:d.version}));break;}
    case 'document-convert':confirmAction('Convert quotation to invoice?','A new draft invoice will preserve the accepted quotation details.',()=>api('documents/convert',{id}));break;
    case 'document-duplicate':await api('documents/duplicate',{id});close();await refresh();notify('A new draft copy is ready.');break;
    case 'print':window.print();break;
    case 'payment-new':{
      const d=state.documents.find(d=>d.id===id),key=crypto.randomUUID();
      form('Record payment · '+d.number,field('amount','Amount received (₹)',decimal(d.total-d.paid-(d.credited||0)),'number',null,true)+field('date','Payment date',today(),'date',null,true)+field('reference','Unique payment reference','','text',null,true)+field('method','Payment method','Bank transfer','text',['Bank transfer','UPI','Cash','Cheque','Card']),b=>api('payments',{...b,documentId:id,key}),'Record payment');break;}
    case 'purchase-new':purchaseForm();break;
    case 'purchase-receive':confirmAction('Receive purchase order?','All ordered quantities will be added to the selected warehouse. Duplicate receipts are blocked.',()=>api('purchases/receive',{id}));break;
    case 'purchase-view':{const p=state.purchases.find(p=>p.id===id);modal(p.number,`<p class="hint">${esc(p.supplier)} · Expected ${esc(p.due)} · ${esc(p.status)}</p>${table(['Item','Quantity','Unit cost','Total'],p.lines.map(l=>`<tr><td>${esc(l.name)}</td><td>${l.quantity}</td><td>${money(l.cost)}</td><td>${money(l.cost*l.quantity)}</td></tr>`))}`);break;}
    case 'expense-new':form('Record an expense',field('description','Description','','text',null,true)+field('category','Category','Operations','text',['Operations','Office','Rent','Payroll','Travel','Marketing','Utilities','Other'])+field('amount','Amount (₹)','','number',null,true)+field('date','Expense date',today(),'date',null,true)+field('reference','Reference'),b=>api('expenses',b),'Record expense');break;
    case 'task-new':form('Plan your next move',field('title','Activity title','','text',null,true,true)+field('due','Due date',today(),'date',null,true)+field('priority','Priority','Normal','text',['Normal','High','Low'])+field('assignee','Assigned to',state.user.name)+field('department','Department','Operations'),b=>api('tasks',b),'Create activity');break;
    case 'task-toggle':{const t=state.tasks.find(t=>t.id===id);await api('tasks',{id,version:t.version,status:t.status==='Completed'?'Pending':'Completed'});await refresh();break;}
    case 'task-open':{const t=state.tasks.find(t=>t.id===id);if(t.module==='inventory')productView(t.record);else if(t.module==='billing')documentView(t.record);else location.hash=t.module;break;}
    case 'order-view':{const o=state.orders.find(o=>o.id===id);modal(o.number,`<p class="hint">${esc(o.customer)} · Due ${esc(o.due)}<br>Tracking: ${esc(o.tracking||'Not recorded')}</p>${table(['Item','Quantity'],o.lines.map(l=>`<tr><td>${esc(l.description)}</td><td>${l.quantity}</td></tr>`))}<div class="section-title">Timeline</div>${o.history.map(h=>`<p class="hint">${esc(h.status)} · ${esc(h.actor)} · ${new Date(h.date).toLocaleString('en-IN')}</p>`).join('')}<div class="form-actions">${button('Open source quotation','document-view',o.documentId)}</div>`);break;}
    case 'order-status':{const o=state.orders.find(o=>o.id===id),status={Confirmed:'Packed',Packed:'Dispatched',Dispatched:'Delivered'}[o.status];form(`${status} · ${o.number}`,field('tracking','Tracking / delivery reference',o.tracking,'text',null,false,true),b=>api('orders/status',{...b,id,version:o.version,status}),`Mark ${status.toLowerCase()}`);break;}
    case 'company-new':companyForm();break;case 'company-edit':companyForm(id);break;
    case 'warehouse-new':form('Add a warehouse',field('name','Warehouse / branch name','','text',null,true,true),b=>api('warehouses',b));break;
    case 'user-new':form('Add a team member',field('name','Name','','text',null,true)+field('email','Email','','email',null,true)+field('password','Initial password (10+ characters)','','password',null,true)+field('role','Role','viewer','text',['administrator','manager','inventory','finance','viewer']),b=>api('users',b),'Create team account');break;
    case 'user-edit':{const u=state.users.find(u=>u.id===id);form('Team access · '+u.name,field('role','Role',u.role,'text',['administrator','manager','inventory','finance','viewer'])+field('active','Access',String(!!u.active),'text',[['true','Enabled'],['false','Disabled']]),b=>api('users',{...b,id,active:b.active==='true'}));break;}
    case 'ask':await ask(id);break;
    case 'export':await exportReport(id);break;
    case 'import':{
      form('Import inventory from Excel',`<p class="hint wide">Create up to 500 items in one import. Every row is validated; if any row fails, nothing is imported. Existing SKUs are not overwritten. Custom field headings must match their field names.</p><div class="wide">${button('Download Excel template','import-template')}</div>`+field('warehouse','Opening-stock warehouse','','text',state.warehouses.map(w=>[w.id,w.name]))+`<label class="field"><span>Excel file (.xlsx, maximum 2 MB)</span><input name="file" type="file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" required></label>`,async(b,f)=>{const file=f.file.files[0];const rows=await GrowExcel.read(file);await api('products/import',{warehouse:b.warehouse,rows});},'Validate & import');break;}
    case 'import-template':download('grow-high-import-template.xlsx',await GrowExcel.buffer([{name:'Inventory',headers:['Name','SKU','Type','Category','Price','Cost','Quantity','Reorder','Unit',...state.fields.map(f=>f.name)],rows:[]}]),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');break;
    case 'backup':{const b=await api('export');download('grow-high-workspace-export.json',JSON.stringify(b,null,2),'application/json');notify('Business data export downloaded.');break;}
  }
}
document.addEventListener('click',e=>{
  const el=e.target.closest('[data-action]');if(el){e.preventDefault();action(el.dataset.action,el.dataset.id||'',el).catch(err=>notify(err.message));}
  const nav=e.target.closest('[data-nav]');if(nav)location.hash=nav.dataset.nav;
});
$('#collapse').innerHTML=icon('menu');$('#theme').innerHTML=icon('sun');$('#notifications').innerHTML=icon('bell');$('#search-icon').innerHTML=icon('search');
$('#collapse').onclick=()=>document.body.classList.toggle('compact');
$('#theme').onclick=()=>{document.body.classList.toggle('dark');localStorage.setItem('gh-theme',document.body.classList.contains('dark')?'dark':'light');};
if(localStorage.getItem('gh-theme')==='dark')document.body.classList.add('dark');
$('#notifications').onclick=()=>{taskFilter='Pending';query='';location.hash='home';if(route==='home')render();};
$('#logout').onclick=async()=>{assistantDraft(null);await api('logout',{});location.href='/';};
$('#global-search').onkeydown=e=>{if(e.key==='Enter'){
  const q=e.target.value.toLowerCase();if(!q)return;
  const matches=[...state.products.filter(p=>!p.archived).map(p=>({name:p.name,sub:p.sku,action:'product-view',id:p.id})),...state.documents.map(d=>({name:d.number,sub:d.customer.name,action:'document-view',id:d.id})),...state.customers.map(c=>({name:c.name,sub:c.email,action:'contact-view',id:'customers:'+c.id}))].filter(r=>(r.name+' '+r.sub).toLowerCase().includes(q)).slice(0,20);
  modal('Search results',`<div class="search-results">${matches.map(r=>button(`<span>${esc(r.name)}</span><small>${esc(r.sub)}</small>`,r.action,r.id)).join('')||empty('No matching records.','Try a product name, SKU, customer, or document number.')}</div>`);
}};
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#global-search').focus();}});
window.addEventListener('hashchange',()=>{query='';page=1;render();if(innerWidth<800)document.body.classList.remove('compact');});
refresh().catch(err=>{$('#content').innerHTML=empty('Unable to open your workspace.',err.message);});
